const KEY = 'chatmate:lang';
const pick = (code) => (code && DICT[code] ? code : null);

// Lingua: scelta salvata, altrimenti quella del browser, altrimenti inglese
export function detectLang() {
  let saved = null;
  try { saved = localStorage.getItem(KEY); } catch {}
  return pick(saved) || pick((navigator.language || '').slice(0, 2).toLowerCase()) || 'en';
}

export let lang = detectLang();

export function setLang(code) {
  if (!pick(code)) return;
  lang = code;
  try { localStorage.setItem(KEY, code); } catch {}
}

// Per l'overlay: lingua fissata dall'indirizzo, senza salvarla
export function useLang(code) { if (pick(code)) lang = code; }

export function t(key, vars = {}, code = lang) {
  const s = DICT[code]?.[key] ?? DICT.en[key] ?? key;
  return String(s).replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? ''));
}

// Applica le traduzioni agli elementi della pagina
export function applyStatic(root = document) {
  document.documentElement.lang = lang;
  root.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-html]').forEach((el) => { el.innerHTML = t(el.dataset.i18nHtml); });
  root.querySelectorAll('[data-i18n-ph]').forEach((el) => { el.placeholder = t(el.dataset.i18nPh); });
}

// Formatta data/ora nella lingua attiva
export const fmtDateTime = (d) => (d ? new Date(d).toLocaleString(lang, { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—');
